#include "ark/onboarding.hpp"
#include <stdexcept>
namespace ark {
arkjson::Value agentOnboard(const AgentSession& session,const arkjson::Value& args){
    using V=arkjson::Value;std::string topic="overview";
    if(auto p=args.find("topic")){if(p->t!=V::Str)throw std::runtime_error("topic must be a string");topic=p->str;}
    if(topic!="overview"&&topic!="sketch"&&topic!="tube"&&topic!="assembly"&&topic!="surfacing"&&topic!="sheet"&&topic!="solids"&&topic!="mesh")throw std::runtime_error("Unknown onboarding topic; choose overview, sketch, tube, assembly, surfacing, sheet, solids or mesh");
    V r=V::makeObj();r.set("product",V::makeStr("ARK"));r.set("name",V::makeStr("Agent-Ready Kernel"));r.set("tagline",V::makeStr("Parametric CAD for people and agents."));r.set("version",V::makeStr("0.9.0"));r.set("topic",V::makeStr(topic));r.set("document",session.info());
    r.set("units",V::makeStr("Lengths mm; plane/feature rotations degrees; sketch angle constraints and trig radians. deg(x) converts degrees to radians."));
    auto list=[](std::initializer_list<const char*> strings){V a=V::makeArr();for(auto s:strings)a.arr.push_back(V::makeStr(s));return a;};
    r.set("workflow",list({"Read this onboarding, then doc_info with detail design for names, values, volumes and bounds. Use doc_get only when expressions or the full document are needed.","Use doc_apply with expected_revision. One batch recomputes once; any failure rolls back the entire batch.","Use created_ids returned by a batch for later feature inputs. Do not assume IDs or use triangle IDs as persistent references.","Inspect native B-rep validation evidence with native_inspect and source inventory with step_inspect; mesh_inspect and raycast see display tessellation.","Keep queries compact; request meshes or snapshots only when needed. Save the parametric document with doc_save."}));
    r.set("available_topics",list({"overview","sketch","tube","assembly","surfacing","sheet","solids","mesh"}));
    r.set("boundaries",list({"OCCT 8.0.1 native solids, loft, fill, NURBS, sweep, surface extrude/revolve, offset, sew, thicken and supported sheet operations produce exact B-reps with explicit validity reports. The viewport mesh and mesh_inspect are display evidence, not exact solid authority; per-face triangulations can have boundary edges.","Mesh features are a separate sampled authority. Exact B-reps enter them only when p.sample=1, and the result does not carry a B-rep. Unsupported approximate downstream operations still reject rather than silently tessellating exact geometry.","Source STEP tube and sheet features are read-only, bounded recognition/projection domains. General arbitrary STEP feature-history reconstruction is unavailable.","Producer-authored semantic references and assembly mates are supported, but arbitrary topology naming, global sketch uniqueness and manufacturing qualification are not established. assembly_info interference is a display mesh overlap check. clearance is the signed exact distance between two B-reps when both bodies have one, and it is not a motion study. GPU acceleration applies to packed transforms/display, not every CAD operation."}));
    r.set("capabilities",list({"Named parameters and expression dependencies","Named construction planes with parent and supported exact reference frames","Dimensioned sketches: points, lines, circles, arcs, wires and interpolating splines, with read-only conflict diagnosis","Exact native OCCT solids, loft, fill, NURBS, sweep, curve, intersection, bridge, surface extrude/revolve, offset, sew and thickening","Sampled mesh import, weld, smooth, decimate, vertex-normal offset and planar hole fill","Authored sheet panel/flange graph and bounded original STEP sheet import","Native STEP export and source-preserving tube projection without Python runtime","Legacy mesh features and grounded assembly mates, with explicit native/mesh boundary","Atomic edits, undo/redo, versioned native document persistence, exact and mesh inspection"}));
    if(topic=="sketch"){
        r.set("tools",list({"doc_apply","plane_inspect","reference_inspect","sketch_inspect","sketch_diagnose","mesh_inspect","mesh_raycast","snapshot","doc_save"}));
        r.set("rules",list({"plane.set{name,kind:plane|axis|frame|point,parent,p:{ox,oy,oz,rx,ry,rz}} creates/updates a named datum. support:{kind:face|midplane|normal_to_curve|tube_path|on_curve|on_face,feature,reference,second_reference?,second_feature?,fraction?,station?,u?,v?} attaches it to authored geometry. Inspect semantic names with reference_inspect. Built-in XY/XZ/YZ cannot be changed. XZ normal=-Y, YZ normal=+X.","sketch.set{name,sketch:{plane,tolerance,entities,constraints}} replaces a sketch. Names identify sketches and entities; changing a referenced name is not an automatic rename.","Entity kind is point|line|circle|spline|arc|wire. dof is [x,y], [x0,y0,x1,y1], [cx,cy,r], arc [cx,cy,r,a0_deg,a1_deg], flattened spline anchors, or a wire of line, minor-arc and cubic segments. construction:true excludes an entity from solid profiles. sketch.patch changes one coordinate. A tangent constraint takes one line and one circle or arc. These save document version 12.","A string coordinate such as 'width/2' is driven exactly by that expression. A numeric coordinate is a free solver variable/initial position. Constraint val/val2 accept numeric values or expressions.","Spline: 2..64 anchors (closed minimum 3), closed:true wraps without repeating first anchor; tension 0..1. Centripetal Catmull-Rom converts to cubic Bezier controls. Legacy profile/display consumers sample to sketch tolerance; native surfacing carries the Bezier spans as exact edges. Sketch tolerance is not manufacturing accuracy.","sketch.entity.set{name,entity:{name,kind,dof,...}} replaces/appends one named entity. Unchanged entities and constraint indexes stay in place. Use it to avoid resending an entire sketch.","Constraint types: fixedX, fixedY, fixed, distance, horizontal, vertical, parallel, perpendicular, radius, coincident, angle, tangent. a/b index entities; pa/pb index line endpoints or spline anchors; circle slot0=center.","Extrude/revolve consumes one closed outer loop via p.sketch. sketch_cut consumes one base feature in inputs and one sketch of disjoint closed loops, with p.depth positive and p.offset along local normal.","Open curves can be saved/inspected but cannot form a solid until explicitly closed. Self-crossing/touching sampled profiles, nested loops and ambiguous joins are rejected.","sketch_inspect reports resolved coordinates, remaining_dofs, local Jacobian rank and profile_ready. Underconstrained does not mean failed. samples:true adds local/world polylines.","Limits: 64 sketches, 128 entities and 256 constraints per sketch, 512 scalar coordinates, 2048 samples per curve/loop and 4096 per profile collection. Tolerance 0.0001..5 mm.","Project an edge or a planar face with kind project, a feature id or unique name, and reference. Offset an earlier curve with kind offset, source and a signed distance in millimetres; positive is to the left of the directed curve, the same side as a wire sweep of +1. Both are driven, so sketch.patch rejects them. feature.edit suppressed skips the feature body and keeps its history and parameters. canvas.set{name,path,width,height,plane?,opacity?} stores a photo rectangle on a plane; the kernel does not decode pixels. A missing file stays a valid document. These save document version 13."}));
        V example;arkjson::parse(R"({"commands":[{"op":"param.set","name":"width","expr":"100"},{"op":"param.set","name":"height","expr":"45"},{"op":"plane.set","name":"design","parent":"XY","p":{"oz":"8","rx":"15"}},{"op":"sketch.set","name":"outline","sketch":{"plane":"design","tolerance":0.03,"entities":[{"name":"skin","kind":"spline","closed":true,"dof":["-width/2","0","-width/3","-height/2","width/3","-height/2","width/2","0","width/3","height/2","-width/3","height/2"]}]}},{"op":"feature.add","type":"extrude","name":"Freeform plate","p":{"sketch":"outline","height":"6"}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("After this example, inspect outline, then change width with param.set. To cut holes, create a circle sketch on design and sketch_cut with the returned extrusion ID, depth='8', offset='-1'."));
    }else if(topic=="tube"){
        r.set("tools",list({"import_step","source_inspect","notch_plan","notch_inspect","tube_inspect","export_step"}));
        r.set("rules",list({"import_step{path,replace:false} adds a supported source tube without replacing the current document. replace:true replaces it. Source stays read-only.","source_inspect{id,progress} reads source/flat openings and evidence; progress 0..1 is display only. Export STEP is always straight.","Designed notched_tube uses dimensions width_mm,height_mm,wall_mm,length_mm,hinge_offset_mm plus notches:[{station,angle,face}]. This ideal model differs from finite source hinges.","Tube programs use round/rect sections and bends [{feed,radius,angle,roll}]. A round tube is an exact annular sweep along the centerline, initially +X, and can enter a boolean or a concentric mate. A rectangular tube stays a display mesh. Tube program previews and imported-source validation have different guarantees.","Use existing source geometry as the authority for hole locations. Never infer missing source features from a screenshot or silently invent unsupported deformation."}));
    }else if(topic=="surfacing"){
        r.set("tools",list({"doc_apply","sketch_inspect","native_inspect","mesh_inspect","export_step","kernel_info","doc_save"}));
        r.set("rules",list({"loft uses native:{sections:[sketch names],guides?:[1..8 open sketch names]} and p:{solid:0|1,ruled:0|1,max_degree?:1..8,smooth?:0|1,compatible?:0|1,continuity?:0|1|2}. Guides force the sections to follow those curves. Sections need the same explicit connected edge topology unless compatible=1. A sketch with only one point is a first or last tip. Solid sections must be closed. Named edges are edge.start.<entity>, edge.end.<entity> and rail.<index>. A smooth loft that fuses sides also lists side.<entity> with status merged and the surviving face. native.faces, native.edges and plane support.reference accept that alias. The document keeps the authored name. Guides save document version 11. A guide or a sweep path may name a curve feature. intersection_curve sections one solid with a datum plane into one wire. bridge continuity 1 is tangent; continuity 2 is tangent plus zero end curvature, not a surface blend. Those features save document version 12.","Sketch lines and circles become native analytic edges. Interpolating spline spans become their exact cubic Bezier control segments, not sampled polylines. Construction entities are excluded.","surface_fill consumes p:{sketch:name} or native:{profile:{frame:[16],entities:[ordered line/circle/bezier boundaries]}}. Boundaries must be explicitly connected and closed; filling is C0 and rejects a boundary residual beyond 1e-6 mm.","bspline_surface consumes native:{poles:rows of [x,y,z],weights?:matching positive grid} and p:{u_degree,v_degree}. Its clamped uniform knots and degrees 1..8 require enough poles. Pole and weight coordinates accept parameter expressions.","thicken consumes one native face/shell feature ID in inputs and p:{thickness} signed and nonzero. It must yield one validated positive-volume solid; it does not certify self-intersection absence or physical manufacturability.","native_inspect reports OCCT B-rep validation and construction evidence compactly. mesh_inspect reports the f32 display tessellation; an open surface or per-face mesh can have boundary edges without implying a failed B-rep.","export_step writes the exact B-rep through a C++ OCCT worker and reads STEP back. Native exact bodies cannot flow into legacy mesh transform/Boolean/pattern/sketch_cut operations.","sweep uses native.section and native.path, each a sketch name or a profile object, plus p.solid, p.correction (default 1) and p.contact (default 0). Correction turns the section orthogonal to the path and corrected-Frenet framing follows the spine. A solid sweep needs a closed section.","extrude_surface uses p.sketch or native.profile, p.distance signed along the profile normal, and p.solid. revolve_surface uses p.angle in (0, 360] degrees and native.axis X, Y or Z; the default axis is the profile Y axis.","offset_surface takes one face or shell input and p.distance. It does not build a solid and does not check offset self-intersections; thicken remains the solid operation. sew takes 2..16 face or shell inputs. p.solid=1 requires one closed shell and no free edges."}));
        V example;arkjson::parse(R"({"commands":[{"op":"param.set","name":"base_radius","expr":"5"},{"op":"param.set","name":"rise","expr":"10"},{"op":"plane.set","name":"upper","p":{"oz":"rise"}},{"op":"sketch.set","name":"lower_circle","sketch":{"entities":[{"kind":"circle","dof":[0,0,"base_radius"]}]}},{"op":"sketch.set","name":"upper_circle","sketch":{"plane":"upper","entities":[{"kind":"circle","dof":[0,0,3]}]}},{"op":"feature.add","type":"loft","name":"Native ruled frustum","p":{"solid":1,"ruled":1},"native":{"sections":["lower_circle","upper_circle"]}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("Run the example batch, then native_inspect the created ID. Edit rise or base_radius and inspect again; export_step writes the exact B-rep."));
    }else if(topic=="solids"){
        r.set("tools",list({"doc_apply","reference_inspect","plane_inspect","native_inspect","export_step","doc_save"}));
        r.set("rules",list({"feature.add type native_solid stores native.op and numeric expressions in p. Exact primitives: box{width,depth,height}, cylinder{radius,height}, sphere{radius}, cone{radius_bottom,radius_top,height}, torus{major_radius,minor_radius}.","Native extrude uses p:{sketch,depth}; line/circle and spline-derived cubic Bezier edges stay exact. union/cut/common take 2..16 earlier inputs, each an id or a unique feature name, and can also list placed assembly nodes in native.instances. Every pattern copy is included. The result is one exact solid with native_inspect. A round tube is an exact annular sweep along its centerline and can enter a boolean. A rectangular tube and a display mesh have no B-rep and are rejected. Two inputs stay at the previous document version. More than two inputs or native.instances save document version 10. shell takes one solid, signed p.thickness and optional native.faces to open, and saves document version 11 with the loft guides. The product version stays 0.9.0. native_inspect point returns a signed distance, negative inside one solid. reference_inspect find returns the unique planar face for a normal such as Z. Point datums, sketch arcs and wires, and curve features save document version 12. transform takes one input and p:{tx,ty,tz,rx,ry,rz} or native.frame[16] column-major rigid matrix.","hole takes one input plus native.cutter:{kind:circle|slot|profile,plane,cx?,cy?,offset?,depth,radius?|length,width}. Profile cutters use p.sketch. Positive depth follows the plane normal; offset can start the cut below its support. A blind depth makes a pocket; a depth crossing the whole body makes a through-cut.","fillet/chamfer take one input, native.edges or native.selection sharp|convex|concave|all with p.min_angle degrees, and p.radius or p.distance. At most 64 edges. draft takes p.angle degrees, native.direction X|Y|Z, native.neutral XY|XZ|YZ, and native.faces or the draftable side faces. Freeform faces reject. linear_pattern takes p.count and p.dx/dy/dz. circular_pattern takes p.count, p.step degrees and native.axis. mirror takes native.plane XY|XZ|YZ or a datum name, or native.face for one planar face. p.fuse defaults to 0 and keeps separate solids; union/cut/common accept that compound. Save writes document version 9 only for these choices; older documents stay at their previous version. Discover names via reference_inspect.","Reference registries bind to the current B-rep digest. OCCT operation history preserves unique face/edge bindings; split/deleted/ambiguous references reject. Boolean tool references use tool.<feature id> namespaces. Some curved faces have stable identity but no unique rigid frame (frame_available:false).", "STEP uses the exact B-rep and independent readback checks. Valid solid/volume checks do not certify all self-intersections, tool access, mechanics or manufacturing."}));
        r.set("next_step",V::makeStr("Create a native primitive or extrude an authored sketch. Discover semantic references, attach a datum and hole, change a dimension, inspect the rebuilt B-rep, then export STEP."));    }else if(topic=="sheet"){
        r.set("tools",list({"doc_apply","sheet_preview","step_inspect","import_sheet_step","native_inspect","export_step","kernel_info","doc_save"}));
        r.set("rules",list({"sheet.create{name,p:{width,thickness,k_factor},base:{id,length}} creates a rectangular base. sheet.flange.add{id,flange:{id?,parent,edge,length,width?,offset?,inner_radius,angle,k_factor?}} adds an explicitly attached flange. Up to 16 flanges; signed angles 0.001..169.999 degrees; unique panel IDs and earlier parents.","sheet.flange.edit/id/entity/values and sheet.opening.edit/id/entity/values preserve identity. Removal with dependants requires explicit cascade:true. Legacy L-bend p:{width,leg_a,leg_b,thickness,inner_radius,angle,k_factor} remains supported and promotes when edited with graph commands.","sheet.opening.add{id,opening:{id?,panel,kind:circle|polygon,x,y,radius,points}} binds a real cut to a named panel. Local expressions panel_length/panel_width/thickness preserve design intent. Flange expressions also expose parent_length/parent_width/edge_length. Legacy numeric panel 0/1 remains supported. Edge/bend-crossing openings reject.","The native result carries formed and flat B-reps and meshes, a declared geometric bend allowance and an explicit K-dependent formed/flat volume difference. K=0.5 gives the midpoint geometric volume model; other K values do not claim material conservation.","step_inspect inventories an original STEP independently. import_sheet_step{path,k_factor,body_index?,root_panel?,replace?} then imports one supported exact body as read-only source_sheet. Multiple bodies require body_index; an equally plausible root-panel tie requires root_panel 0 or 1.","Original STEP sheet import supports a single flat panel or two constant-width rigid panels joined by one complete cylindrical bend, with owned rigid-panel openings. Curved-zone cuts, segmented or multiple bends and ambiguous source topology reject.","native_inspect returns source hash, body, bend/opening census, measured flat length, and source/refold evidence without B-rep buffers. Source report source_projection_verified is geometric proof, not manufacturing qualification.","Authored panel trees validate analytic integrals, flat/formed interference and an independent neutral-line refold by whole-solid difference. sheet_preview{id,progress} returns display-only sequential panel poses; motion trajectory and press-tool collision are not certified.","export_step defaults to flat for sheet features; pose:formed writes the formed B-rep. Imported-source export rebinds source bytes when present and the verified embedded payload for portable documents. Changed existing source bytes reject."}));
        V example;arkjson::parse(R"({"commands":[{"op":"feature.add","type":"sheet_metal","name":"Two-flange sample","p":{"width":60,"leg_a":80,"leg_b":50,"thickness":2,"inner_radius":5,"angle":90,"k_factor":0.5},"native":{"openings":[{"panel":0,"kind":"circle","x":25,"y":20,"radius":4},{"panel":1,"kind":"polygon","points":[[15,20],[25,20],[25,30],[15,30]]}]}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("Run the designed-sheet example and native_inspect the created ID. Use export_step for flat or pose:formed; inspect an original STEP before a separate import_sheet_step."));
    }else if(topic=="assembly"){
        r.set("tools",list({"doc_apply","reference_inspect","assembly_info","mesh_inspect","mesh_raycast","doc_save"}));
        r.set("rules",list({"assembly.add{name,parent,feature,p,visible,fixed}: parent=0 root, feature=0 group, otherwise an existing feature id or its unique name. The saved document stores the numeric id. pattern with type linear or circular, count, and dx/dy/dz or step/axis repeats that one part. A mate moves the pattern rigidly and degrees of freedom count the node once. fixed:true grounds a part instance at its authored placement.","p is rigid tx/ty/tz/rx/ry/rz expressions relative to parent. Shared feature definitions produce instances, not duplicated geometry.","mate.add{a,b,type,reference_a,reference_b,value?,fraction_a?,fraction_b?}, mate.edit and mate.remove take a numeric mate id, or omit id and pass endpoints a and b in either order. Endpoints a and b accept a sibling part instance id or its unique name; the saved mate stores ids. feature.edit, feature.remove, assembly.edit and assembly.remove accept a unique name as well as an id. assembly.edit parent accepts a unique group name; parent 0 stays the root. Each mate-connected component needs a fixed instance.","Mate types: concentric aligns axes; coincident aligns origins and +Z; contact opposes +Z normals with zero plane gap; distance measures signed mm along A +Z; angle measures 0..180 degrees between +Z axes.","Local references origin/X/Y/Z/XY are available. Analytic cylinder, cone and torus meshes run along +Y. A native_solid cylinder, cone or torus uses local +Z. Promoting an analytic cylinder, cone or torus applies Rx(-90 degrees), so the exact B-rep axis becomes +Z. Mate references Z, origin and XY use the instance frame +Z. Semantic reference axis is the exact B-rep cylinder axis. The analytic mesh axis is not retargeted. A round tube exact axis is its centerline and starts along +X. The tube display mesh uses that same centerline. For exact semantic face, edge and axis references, discover producer-authored names with reference_inspect{id}; stale, split or deleted references reject.","assembly_info returns solved world matrices, BOM, mate definitions and diagnostics: position/angle residuals, local Jacobian rank, remaining DOFs and unconstrained instances. A successful underconstrained solve keeps authored placement for free coordinates.","Mates place instances but do not fuse bodies. assembly_info can probe a candidate mate without saving it. interference lists display mesh overlaps and stays the cheap screen. clearance:{a,b} is the signed exact distance in mm between two B-reps when both have one; positive is a gap and negative is penetration, with the two faces. A body without a B-rep sets clearance_checked false. measure is read-only distance and angle between two semantic frames and does not change the revision. Neither is a motion study. Pass interference:true to raise the triangle budget. Fuse placed parts with native_solid union, cut or common through feature inputs or native.instances. Mesh queries and snapshot accept node, a unique name or an id, plus copy for one pattern placement, never both id and node. doc_info detail design lists copy counts without mesh buffers."}));
        r.set("next_step",V::makeStr("Inspect the current assembly and exact reference names, ground one part instance, then add sibling mates in a single revision-checked doc_apply batch. Read assembly_info diagnostics after the solve."));
    }else if(topic=="mesh"){
        r.set("tools",list({"doc_apply","import_mesh","mesh_inspect","mesh_get","mesh_raycast","export_mesh","doc_save"}));
        r.set("rules",list({"The kernel does not decode a photo. A prismatic outline becomes a sketch wire, then an extrude. A freeform photo becomes mesh_body positions plus grid:{nu,nv}: nu and nv are integers from 2 to 256, positions are row-major xyz with nu*nv points, and the kernel builds the triangles. grid and indices together are rejected. The result is a display mesh, not an exact B-rep.","mesh_body stores mesh:{positions,indices} in the document. import_mesh{path,weld_mm?,name?,expected_revision?} reads STL or OBJ once; the file is not linked. Caps are 12288 vertices and 4096 triangles, coordinates within 1e6 mm, and a 4 MiB document. Coordinates are evaluated as f32.","mesh_weld{inputs:[id],p:{epsilon}} merges vertices. epsilon defaults to 1e-4 mm and must be in (0, 1]. Degenerate triangles are dropped.","mesh_smooth{inputs,p:{iterations,lambda,pin_boundary}} is uniform Laplacian. iterations is 1..64, lambda defaults to 0.5 in (0, 1], and boundary vertices stay fixed unless pin_boundary=0.","mesh_decimate{inputs,p:{ratio}} collapses interior edges with quadric error at the midpoint. ratio is in [0.05, 1]. Boundary loops are preserved. A result that would open a closed mesh or change the boundary count is rejected. target_reached is false when the ratio cannot be met. At most 12000 input triangles.","mesh_offset{inputs,p:{distance}} moves vertices along averaged normals. Closed meshes are oriented outward first, so positive distance grows them. Corners do not move by the full distance. This is not an exact surface offset and self-intersections are not checked.","mesh_fill caps each boundary loop that lies within 1e-4 mm of one plane, using an ear clip of at most 256 vertices. It rejects an existing lone triangle, a self-intersecting loop, or a curved boundary. Use surface_fill for a curved exact patch.","Exact B-rep features need p.sample=1 before any mesh feature. mesh_model on mesh_inspect records the operation and states mesh_authoritative=true and exact_geometry=false. native_inspect and export_step do not apply to mesh features."}));
        V example;arkjson::parse(R"({"commands":[{"op":"feature.add","type":"mesh_body","name":"Open triangle","mesh":{"positions":[0,0,0, 1,0,0, 0,1,0, 0,0,1],"indices":[0,2,1, 0,1,3, 0,3,2]}},{"op":"feature.add","type":"mesh_fill","inputs":[1]}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("Run the example, then mesh_inspect the fill id. The report includes mesh_model and a signed volume only when the capped triangle set is closed and consistently oriented."));
    }else r.set("next_step",V::makeStr("Choose sketch, solids, surfacing, sheet, tube, assembly or mesh for a targeted contract. No language model or Python runtime is required for deterministic native geometry operations."));
    return r;
}
}
